/** Dispatch a layer's matrix by name and index (type aliases cannot be passed around). */
export type Mat<N extends string, L extends number, X extends Strs> = [N, L] extends ["q", 0]
  ? L0_q<X>
  : [N, L] extends ["k", 0]
  ? L0_k<X>
  : [N, L] extends ["v", 0]
  ? L0_v<X>
  : [N, L] extends ["proj", 0]
  ? L0_proj<X>
  : [N, L] extends ["fc", 0]
  ? L0_fc<X>
  : [N, L] extends ["mlp", 0]
  ? L0_mlp<X>
  : [N, L] extends ["q", 1]
  ? L1_q<X>
  : [N, L] extends ["k", 1]
  ? L1_k<X>
  : [N, L] extends ["v", 1]
  ? L1_v<X>
  : [N, L] extends ["proj", 1]
  ? L1_proj<X>
  : [N, L] extends ["fc", 1]
  ? L1_fc<X>
  : [N, L] extends ["mlp", 1]
  ? L1_mlp<X>
  : [N, L] extends ["q", 2]
  ? L2_q<X>
  : [N, L] extends ["k", 2]
  ? L2_k<X>
  : [N, L] extends ["v", 2]
  ? L2_v<X>
  : [N, L] extends ["proj", 2]
  ? L2_proj<X>
  : [N, L] extends ["fc", 2]
  ? L2_fc<X>
  : [N, L] extends ["mlp", 2]
  ? L2_mlp<X>
  : [N, L] extends ["q", 3]
  ? L3_q<X>
  : [N, L] extends ["k", 3]
  ? L3_k<X>
  : [N, L] extends ["v", 3]
  ? L3_v<X>
  : [N, L] extends ["proj", 3]
  ? L3_proj<X>
  : [N, L] extends ["fc", 3]
  ? L3_fc<X>
  : [N, L] extends ["mlp", 3]
  ? L3_mlp<X>
  : never;


